CREATE TABLE public.ugc_comments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    post_id uuid,
    review_id uuid,
    parent_id uuid,
    customer_id uuid NOT NULL,
    author_display_name text,
    body text NOT NULL,
    status text DEFAULT 'published'::text NOT NULL,
    moderation_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    product_id uuid,
    kind text DEFAULT 'comment'::text NOT NULL,
    author_role text DEFAULT 'customer'::text NOT NULL,
    CONSTRAINT ugc_comments_body_check CHECK (((char_length(body) >= 1) AND (char_length(body) <= 2000))),
    CONSTRAINT ugc_comments_has_parent CHECK (((product_id IS NOT NULL) OR (post_id IS NOT NULL) OR (review_id IS NOT NULL))),
    CONSTRAINT ugc_comments_kind_chk CHECK ((kind = ANY (ARRAY['comment'::text, 'question'::text, 'tip'::text]))),
    CONSTRAINT ugc_comments_role_chk CHECK ((author_role = ANY (ARRAY['customer'::text, 'seller'::text, 'staff'::text]))),
    CONSTRAINT ugc_comments_status_check CHECK ((status = ANY (ARRAY['published'::text, 'hidden'::text, 'removed'::text])))
);

